"""
Content/style cleanup pass across every page.

Audited all live pages directly (verified on GitHub, not from memory)
against your list:
  - fake reviews/testimonials: none found
  - vague hero text: none found (no marketing/hero sections exist --
    every page is a functional form or dashboard)
  - fake metrics / fake counters: none found
  - emoji icons: none found
  - scroll animations: none found (no @keyframes/animate- classes anywhere)

Two real hits, both fixed:
  - Em dashes: every page <title> and header used "ScholaCore -- X"
    with an em dash; also present in a couple of code comments, one
    user-visible placeholder ('-' shown when a teacher has no uploaded
    docs), and throughout README.md. All replaced (colons in titles,
    semicolons in prose, "None uploaded" for the placeholder).
  - Pill-shaped elements: the status badges (pending/approved/rejected)
    used rounded-full. Changed to rounded-md. Note: the actual buttons
    (.sc-btn) were already rounded-md, not pill-shaped, so no button
    changes were needed.

Run on your Windows machine with the repo already cloned.

Usage:
    python fix_scholacore_content_cleanup.py [path_to_repo]
"""
import base64, os, subprocess, sys

DEFAULT_REPO = r"C:\Users\Bosslady\SCHOLACORE\scholacore"

FILES = {
    'admin-dashboard.html': '',
    'pay.html': '',
    'privacy-policy.html': '',
    'student-signup.html': '',
    'teacher-portal.html': '',
    'teacher-vetting.html': '',
    'terms-of-service.html': '',
    'src/pages/admin-dashboard.ts': '',
    'src/telegram.ts': '',
    'src/pages/pay.ts': '',
    'src/style.css': '',
    'README.md': '',
}


def run(cmd, cwd):
    print(">", " ".join(cmd))
    result = subprocess.run(cmd, cwd=cwd, capture_output=True, text=True)
    if result.stdout.strip():
        print(result.stdout)
    if result.returncode != 0 and result.stderr.strip():
        print(result.stderr)
    return result.returncode == 0


def main():
    repo_root = sys.argv[1] if len(sys.argv) > 1 else DEFAULT_REPO
    if not os.path.isdir(repo_root):
        print(f"Repo path not found: {repo_root}")
        sys.exit(1)
    if not os.path.isdir(os.path.join(repo_root, ".git")):
        print(f"{repo_root} is not a git repository (no .git folder). Aborting.")
        sys.exit(1)

    written = []
    for rel_path, b64_content in FILES.items():
        dest = os.path.join(repo_root, rel_path.replace("/", os.sep))
        os.makedirs(os.path.dirname(dest), exist_ok=True)
        with open(dest, "wb") as f:
            f.write(base64.b64decode(b64_content))
        written.append(rel_path)
        print(f"wrote: {rel_path}")

    print(f"\n{len(written)} files written to {repo_root}")

    if not run(["git", "add"] + written, repo_root):
        sys.exit(1)
    commit_msg = "Content cleanup: remove em dashes (titles/headers/comments/README), remove pill-shaped status badges"
    if not run(["git", "commit", "-m", commit_msg], repo_root):
        print("Nothing to commit or commit failed -- check output above.")
        sys.exit(1)
    run(["git", "push", "origin", "main"], repo_root)


if __name__ == "__main__":
    main()
